local _, ZoneLore = ...

ZoneLore.Zones = {
	[947] = {
		name = "Azeroth",
		short = "Azeroth is the name of the world in which the majority of the Warcraft series is set. At its core dwells a slumbering worldsoul, the nascent spirit of a titan.",
		full = "Azeroth is the name of the world in which the majority of the Warcraft series is set. At its core dwells a slumbering worldsoul, the nascent spirit of a titan. Floating within the infinite reaches of the Great Dark Beyond, Azeroth once fell to the corruption of the Old Gods and their Black Empire, until the Pantheon of Order defeated them and began the Ordering of the planet. It has since been populated by a multitude of different races and creatures, some native to the planet, others from different worlds; all carving out territories for themselves. However, Azeroth also became the target of enemies from beyond, including the chaotic armies of the Burning Legion and the voracious forces of the Void. Those responsible for the world's safety are not a united group; Azeroth's history is filled with wars and conflicts, and in modern times, the Alliance and the Horde are the major political factions of the mortal races. Each represents the unification of various racial, cultural, and philosophical civilizations. Despite their incessant conflicts and bloodshed, both factions treasured Azeroth, believing it should be cared for and protected, and in times of grave danger, they are willing to work together in the face of a common foe.\n\nAlthough unnamed and numerous, it is thanks to the brave adventurers that Azeroth, and the universe itself, have been saved on numerous occasions. There are also many organizations dedicated to the protection of the world, which maintain an independent position during global conflicts, such as the Cenarion Circle, Earthen Ring, Kirin Tor, Argent Crusade, and Kingdom of dragons among many others.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Barrens to the west and the coastal lands of Azshara to the north.",
		full = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Barrens to the west and the coastal lands of Azshara to the north. The land of Durotar is rocky, and the soil is cracked and red, not unlike the orcs' homeland of Draenor. The land has many crags and canyons, where various dangerous creatures take residence. It is a harsh land to survive in; it is very dry and hot, and the vegetation and freshwater access is sparse. The orcs, however, see a harsh beauty in the land that reminds them of their home world. Durotar is a proving ground for young orcs, who are sent to the Valley of Trials to complete several rites of passage before they are considered fit for the challenges that lie ahead. Durotar is the new homeland of the orcs and the site of the orcs' principal city of Orgrimmar. While the orcs founded their city of Orgrimmar here, Durotar has become something of a haven for all of the Horde races, especially the trolls.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "The green, verdant plains of Mulgore are home to the noble tauren. Their ancestral homeland is nestled in the foothills of the Stonetalon Mountains to the north, and protected by a natural wall of mountains on all sides.",
		full = "The green, verdant plains of Mulgore are home to the noble tauren. Their ancestral homeland is nestled in the foothills of the Stonetalon Mountains to the north, and protected by a natural wall of mountains on all sides. The only pass through these mountains leads into the Barrens to the east.\n\nA land of windswept mesas and grassy plains, Mulgore is the tauren's ancestral homeland. Centaur often send raiding parties into Mulgore, and the tauren, now with the help of their Horde allies, beat them back. Tauren are naturally a nomadic people, and their tent cities are scattered across the landscape and change with the seasons and the weather. Now that they are members\n\nof the Horde, the tauren have constructed several permanent settlements, including their capital of Thunder Bluff.\n\nMulgore provides bounty for the hunt, as a diversity of wild beasts roam the rolling plains and climb the foothills of the surrounding range. In the northern section of Mulgore, the mesas of Thunder Bluff tower above the plains, casting long shadows. Bloodhoof Village is centrally located surrounded by the clear waters of Stonebull Lake, and further south on the protected cliffs of Red Cloud Mesa, Camp Narache stands as the principal training camp for all young tauren.\n\nDespite the serene landscape and the pine-scented breeze, Mulgore is fraught with trouble. Brambleblade Ravine and the sacred Red Rocks are overrun by quilboars. The goblin-run Venture Company infests the three sacred water wells of Mulgore as well as their Venture Co. Mine in the eastern mountain face. The Windfury harpy tribe lay claim to the extreme northern reaches of Mulgore and the southeast mountain face. The Alliance makes its presence known at the Bael'dun Digsite, where dwarves scour the mountains for traces of their shrouded ancestry, and a tribe of gnolls known as the Palemane make their home at the cave called Palemane Rock as well as scattered camps along the southern mountains.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "The Barrens",
		short = "The Barrens is a large zone in central Kalimdor controlled mostly by the Horde. It is a massive savanna, with a few oases in the north-central region around the Crossroads.",
		full = "The Barrens is a large zone in central Kalimdor controlled mostly by the Horde. It is a massive savanna, with a few oases in the north-central region around the Crossroads. Before the upheaval, several large kaldorei cities stood here. Now, those brave few willing to scrape out a life on the arid plains inevitably run afoul of centaur warbands or quilboar raiding parties. Despite its often uninviting terrain and hostile inhabitants, the Barrens receive a good deal of interest from Alliance and Horde alike, as well as races native to Kalimdor. Trade routes crisscross the landscape leading to and from more inviting regions, and the most notable route is the Gold Road that runs north-to-south through the Barrens and beyond. Rumours suggest that precious minerals and treasure-filled ruins await those with the courage to investigate.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Kalimdor [ˈkælɪmdɔɹ] (Titan and Darnassian for land of eternal starlight) is one of the main continents of Azeroth. The continent lie to the west of the Great Sea and to the east of the Forbidding Sea.",
		full = "Kalimdor [ˈkælɪmdɔɹ] (Titan and Darnassian for land of eternal starlight) is one of the main continents of Azeroth. The continent lie to the west of the Great Sea and to the east of the Forbidding Sea. Kalimdor can be further divided into three regions known as Northern Kalimdor, Central Kalimdor, and Southern Kalimdor. It is home to the night elves, orcs, tauren, trolls, and draenei. Other races present include the ogres, centaur, naga, demons, and other, more minor races.\n\nKalimdor was primarily the domain of the night elves in the ten thousand years between the War of the Ancients and the Battle of Mount Hyjal. In the years since the Third War, night elf dominion has given way as the tauren adopted a more centralized system and accepted their allies, the orcs and the trolls of the Horde into their midst. The recent arrival of the draenei also adds a new power to the map. The continent is now a politically divided one, the Horde have established strong control in the central and eastern areas while the night elves, now aided by the draenei, preserve footholds in northwestern areas.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Eastern Kingdoms",
		short = "The Eastern Kingdoms (occasionally called Azeroth or the Old World) is one of the main continents of Azeroth. The continent lie to the east of the Great Sea and to the west of the Forbidding Sea.",
		full = "The Eastern Kingdoms (occasionally called Azeroth or the Old World) is one of the main continents of Azeroth. The continent lie to the east of the Great Sea and to the west of the Forbidding Sea. They are made up of a group of smaller continents (Azeroth, Khaz Modan and Lordaeron) formed from the original continent of Kalimdor following the Great Sundering. The central part of the Eastern Kingdoms is dominated by the mountains of Khaz Modan and the Redridge Mountains. It is home to the dwarves, gnomes, high and blood elves, humans, worgen, and the Forsaken. Other races present include the orcs, goblins, draenei, naga, ogres and other, more minor races.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alterac Mountains",
		short = "Alterac Mountains is the location of the former nation of Alterac and the city-state of Dalaran, and its chief settlements included Alterac City, Dalaran and Strahnbrad.",
		full = "Alterac Mountains is the location of the former nation of Alterac and the city-state of Dalaran, and its chief settlements included Alterac City, Dalaran and Strahnbrad. The central mountains have been overrun by ogres, while the organization called the Syndicate controls Strahnbrad and other areas. Dalaran was enclosed within an impregnable magic shell before the city was lifted in the air and moved to Northrend. A high, wooded region, the Alterac Mountains see much rainfall and its skies are constantly overcast. Crushridge ogres and the Syndicate, a wicked group of rogues led by fallen human nobles, clash repeatedly for control of this land.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathi Highlands",
		short = "The Arathi Highlands are located in southeastern Lordaeron, east of Hillsbrad Foothills and south of the Hinterlands.",
		full = "The Arathi Highlands are located in southeastern Lordaeron, east of Hillsbrad Foothills and south of the Hinterlands. It is a flat but craggy region that has traditionally been the home of the humans of Arathor, who gave the region its name. The main hubs of activity are now Refuge Pointe and Hammerfall, which houses bases for Alliance and Horde, respectively. The large city of Stromgarde lies in ruins to the southwest, and pockets of Syndicate resistance dot the land. The Boulderfist ogres also infest Arathor, and prove to be a constant threat to the Alliance, Horde, and Syndicate factions vying for supremacy.\n\nThe Syndicate, Boulderfist ogres and the beleaguered human defenders of Stromgarde battle for supremacy in this gray, dismal realm. Prince Galen Trollbane leads the human defenders, and his mighty city of Stromgarde is a ruined battleground where the three factions wage guerrilla war. The Trollbane family's holdings include several ancient human artifacts, and a group called the Caretakers protects and preserves the most important pieces. To the south is the Thandol Span, a massive dwarven construction that bridges the canal between Lordaeron and Khaz Modan.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Badlands",
		short = "The Badlands is a region in Khaz Modan accessed via the Searing Gorge to the west and Loch Modan to the north.",
		full = "The Badlands is a region in Khaz Modan accessed via the Searing Gorge to the west and Loch Modan to the north.\n\nThe Badlands are a cracked desert of dry earth, scattered boulders, and winding canyons. Dark Iron dwarves clash with ogres and drakes, while Horde orcs man a fortress to keep watch on their renegade brethren in the eastern lands. Ironforge prospectors search this desolate land for Titan artifacts, inspired by the recently unearthed Uldaman -- an immense ruin that held the first clues to the dwarves' lofty origins. Stonevault troggs, released after millennia of slumber, slaughtered the explorers and viciously defend their stolen city.\n\nOnly the hardiest of creatures can survive in the arid wastes, such as feral coyotes, cougars and buzzards. In the far east is a region inhabited by black dragon spawn. Scattered across the Badlands are camps of ogres of the Dustbelcher tribe. In the northwest is a tiny Horde outpost. The northern reaches of this rugged land are home to ruins that were the workings of the ancient race, the earthen. These ruins are known as Uldaman. Dark Iron dwarves also have a large fortress just south of Uldaman.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Blasted Lands",
		short = "The Blasted Lands bear that name for a reason: they were twisted by the magic that brought the Dark Portal into being, spewing the rampaging Horde into Azeroth.",
		full = "The Blasted Lands bear that name for a reason: they were twisted by the magic that brought the Dark Portal into being, spewing the rampaging Horde into Azeroth.\n\nThis wasted desert of red clay is home to the original Dark Portal. Nethergarde Keep, a Stormwind fortress of dour mages and paladins, keeps watch over the portal and the demons and ogres that would abuse its power.\n\nNow, the wretched land hosts few inhabitants and no significant settlements. Magic that leaked through the Dark Portal warped the Blasted Lands, leaving an infertile desert landscape. Hardy desert species like Basilisks, Scorpions and Hyenas have since colonized the area. The red rocks of the region do not come by their color naturally. The original tan color was transmuted into the unearthly crimson by searing heat and chaotic energies when the Dark Portal was destroyed.\n\nThere is but one usable road in the Blasted Lands, guarded at the north by Nethergarde Keep's grim mages. They have the unenviable task of watching the Dark Portal, guarding the rest of the continent from the demons in the south and protecting themselves from the ogre tribes that roam the desert. The weather here is dry and hot during the day and bitterly cold at night. Mountains block any moisture that may come from the Swamp of Sorrows to the north, and no rivers grace this land. The eastern coast will occasionally get storms from the sea, but these downpours come so quickly the water merely runs off the packed earth and back into the sea.\n\nThe keepers of Nethergarde have an uptight and uncheerful disposition that seems appropriate in light of the danger they face daily. The warriors and mages fight every day with the ogre magi and demons that threaten either to destroy the keep or take over the Dark Portal. This tightly knit community experiences little crime, however. Those found breaking the agreements they take on when accepting a post at the Keep are sent for a time to the Stockade in Stormwind. These mages cannot afford any dissension in the ranks. If you must visit the Blasted Lands, remember that the Nethergarde mages are the only hospitable people in the entire region for Alliance. And they're not even that hospitable.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal Glades",
		short = "On the northern coast of Lordaeron lies the eerie Tirisfal Glades.",
		full = "On the northern coast of Lordaeron lies the eerie Tirisfal Glades. The unofficial kingdom to the Forsaken, servants of the Banshee Queen Sylvanas Windrunner, the wooded hills are seeped through with the curse of the Lich King's plague. The sky over Tirisfal is eternally gloomy and tinted a blighted green, and the trees and other flora desperately cling to their last shreds of life.\n\nAlthough tainted and melancholy, Tirisfal still very much has its own unique, haunting beauty, particularly in such areas as the stony North Coast, the village of Brill, and the deep atmosphere of the ruined Agamand Mills.\n\nTirisfal Glades is home not only to the Forsaken, but to their enemies as well. The Scarlet Crusade has several outposts here, including the seat of their religious faith, the Scarlet Monastery. The minions of the Scourge are also ever present, tainting the derelict farmsteads and dilapidated mills with their foul presence.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silverpine Forest",
		short = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains.",
		full = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains. The forest is eerily silent save for the occasional unnatural howling echoing among the trees. Mossy overhangs shiver in the cold breeze, and the trees are all sickly or dying. Dilapidated farmsteads and abandoned mines dot the land, home now to the darker denizens of the woods.\n\nThis woodland is haunted and wild, characterized by its tall, silver-barked pines towering over grassy knolls. The Alliance once protected Silverpine Forest when it was verdant and lively. Now the place is shrouded in ghostly mists. Forsaken control the northern forest and constantly clash with the wretched Rot Hide gnolls. What remains of the human population retains control of the southern forest, but they are desperate and their forces thinly stretched. Dalaran sends frequent expeditions into Silverpine to defend these people and study the undead plague and worgen curse -- a mysterious affliction that causes its victims to transform into bloodthirsty, lycanthropic worgen when the moon rises.\n\nGilneas and the Hillsbrad Foothills border the forest to the south, while Tirisfal Glades lays to the north. Lordamere Lake serves as Silverpine's eastern border.\n\nThough the territory belongs to the Forsaken, their claim is disputed by the wizards of Dalaran and agents of the Scourge who have taken possession of some of the ruined fields and steadings. Rothide gnolls operate from the mysterious Fenris Isle, and fiercely attack anyone who dares approach their dealings. In the southwest lays Pyrewood Village, whose people have fallen under archmage Arugal's curse, transforming into bloodthirsty worgen at night-time. Arugal makes his home in the nearby darkened towers of Shadowfang Keep.\n\nSilverpine Forest frequently sees battle, as Alliance forces from Southshore journey to the forsaken woods to attack the Sepulcher or enter Shadowfang. It is the edge of the Forsaken homeland, and the southernmost point where effects of the undead plague can be seen in the plant life.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Western Plaguelands",
		short = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south.",
		full = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south. It is filled with a smoky gray mist and the creatures here are blighted and sick, angrily attacking anyone who wanders too close with surprising ferocity. The land is also home to countless undead who infest the ruins of Andorhal, the four cauldron fields, and Sorrow Hill. The Scarlet Crusade has a significant holding in and around Hearthglen to the north, and the Alliance has settled in the small Chillwind Camp to the south.\n\nLike their eastern counterparts, the Western Plaguelands were once fertile and beautiful but are now gray, blighted and noxious. Undead wander the land and haunt the abandoned towns and farmsteads. The largest Scourge city here is Andorhal, beneath which is an underground complex housing the undead's School of Necromancy. The Scarlet Crusade strikes against the Scourge from Hearthglen. The only place of any sanity in the Western Plaguelands is Uther's Tomb, a consecrated monument to the fallen hero Uther Lightbringer.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Eastern Plaguelands",
		short = "The Eastern Plaguelands is the more heavily devastated half of the Plaguelands, the remnants of the Kingdom of Lordaeron. They are located east of the Western Plaguelands and north of the Hinterlands.",
		full = "The Eastern Plaguelands is the more heavily devastated half of the Plaguelands, the remnants of the Kingdom of Lordaeron. They are located east of the Western Plaguelands and north of the Hinterlands.\n\nThe Scourge's rule here is supreme. Their southern capital of Stratholme is here, under the command of the lich, Kel'Thuzad. The ground is brown, ugly, and sick, the trees corrupted into giant mushrooms and the air polluted with orange mist. Undead, necromancers, and Damned cultists prowl the land. The Scarlet Crusade boasts a large army and battles fervently and vainly against the Scourge; outsiders are also unwelcome. Amani forest trolls strike from the north, attempting to reclaim their ancestral empire.\n\nThe area is roamed by mutant creatures and soldiers of the Scourge, while members of the Scarlet Crusade fight a constant battle to drive the Scourge out of Stratholme from their Chapel and key base at Tyr's Hand. Only a small camp maintained by the Argent Dawn remains friendly to all, welcoming adventurers that would lend a strong arm or spell. Located at Light's Hope Chapel, this staging area serves as a last bastion of Light in a land blanketed in darkness.\n\nMembers of the Horde and the Alliance battle in A Game of Towers for four strategic ruined outposts spread throughout the land. Controlling these towers gives area-wide benefits and certain towers provide other, unique advantages.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Hillsbrad Foothills",
		short = "The Hillsbrad Foothills (sometimes referred to as simply Hillsbrad) is a mid-level zone most suitable for players around level 25.",
		full = "The Hillsbrad Foothills (sometimes referred to as simply Hillsbrad) is a mid-level zone most suitable for players around level 25. Located in the Southern end of the North Island of (Eastern Kingdoms), the hills are home to the towns of Southshore and Hillsbrad Fields (Alliance), and Tarren Mill (Horde). Some notable locations, such as Durnholde Keep and Azurelode Mine can also be found here. Since this area lies outside of Thoradin's Wall, it is considered as a crossroads between Alliance and Horde players, which makes combat between the two factions likely.\n\nHillsbrad is relatively safe and stable. Its hills are green and pastoral, its meadows fertile and its soil rich. Humans loyal to the Alliance control Hillsbrad from the town of Southshore, though the Syndicate, murlocs and Forsaken threaten their serenity.\n\nThe current Hillsbrad Foothills is made up of the former Hillsbrad Foothills region, Southshore region, and the Tarren Mill region. It is also one of the sub-regions of the Alterac Valley region.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "The Hinterlands",
		short = "The Hinterlands, located in the Northern part of the Eastern Kingdoms, are probably most notable for the Wildhammer dwarves who make their residence at Aerie Peak in the west.",
		full = "The Hinterlands, located in the Northern part of the Eastern Kingdoms, are probably most notable for the Wildhammer dwarves who make their residence at Aerie Peak in the west. The Wildhammers have always been staunch allies of the Alliance. It is from the Hinterlands that these dwarves find and tame their world-renowned gryphons. The Razorbeak gryphons roam wild in this region.\n\nAlso in the Hinterlands is one of the last remaining settlements of the high elves in Lordaeron at the Quel'Danil Lodge.\n\nThe Hinterlands are also home to a large population of forest trolls, which are divided into three separate tribes. The Revantusk tribe is the only one of the three that has declared sides in the Horde/Alliance conflict and support the warchief Thrall of the Horde. The Vilebranch tribe holds residence in the massive troll city of Jintha'Alor as well as the Altar of Zul while the Witherbark tribe holds the smallest influence, hailing from the temples of Shadra'Alor.\n\nIn the northern part of the region is the ancient, massive tree, Seradane where the agents of the Green dragonflight have been corrupted. A massive portal on the side of the tree connects the servants of the Aspect Ysera to her own realm, the Emerald Dream.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Dun Morogh is a snowy region located between the magma-strewn wasteland of the Searing Gorge to the south, the gentle ridges of Loch Modan to the east, and the swampy Wetlands to the north.",
		full = "Dun Morogh is a snowy region located between the magma-strewn wasteland of the Searing Gorge to the south, the gentle ridges of Loch Modan to the east, and the swampy Wetlands to the north. Dun Morogh is home to both the gnomes of Gnomeregan and the Ironforge dwarves and is the location of the major city of Ironforge. The Khaz Modan mountains surround Dun Morogh on all sides, making it accessible only by certain passes that are currently watched over by dwarven troops.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Searing Gorge",
		short = "The Searing Gorge is a contested zone in the Eastern Kingdoms for players in the 43-52 range. It is home to a group of exceptionally stout dwarves called the Thorium Brotherhood, who have split from the Dark Iron clan.",
		full = "The Searing Gorge is a contested zone in the Eastern Kingdoms for players in the 43-52 range. It is home to a group of exceptionally stout dwarves called the Thorium Brotherhood, who have split from the Dark Iron clan.\n\nFor the Alliance, the entrance to the Searing Gorge in Loch Modan is locked until the [Key to Searing Gorge] is obtained via a quest line that culminates in At Last! (level 48 quest). However, any Rogue with lockpicking of at least 225 can pick the doors. An alternate path can be found in the Badlands just south of Kargath. This is the primary Horde entrance, as they have no way of obtaining the key.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Burning Steppes",
		short = "The Burning Steppes hold the only accessible land passage from the Kingdom of Stormwind to Khaz Modan and Lordaeron. The highway is thus well-traveled, but still very dangerous.",
		full = "The Burning Steppes hold the only accessible land passage from the Kingdom of Stormwind to Khaz Modan and Lordaeron. The highway is thus well-traveled, but still very dangerous. Now virtually abandoned by the Kingdom of Stormwind, the Burning Steppes is controlled by minions of the black dragonflight and agents of the firelord Ragnaros.\n\nThis rugged region is full of craggy foothills, scattered boulders and warring factions. Rivers of lava dot the landscape, as well as charred earth and burning ruins. The sky is a red hue here, due to sporadic eruptions from Blackrock Mountain. Blackrock Spire, an orc stronghold in the Second War, stands proud and defiant among the mountains. Dark Iron dwarves control the fortress's deeps, though rumor has it that Ragnaros the Fire Lord still broods in the shadows. Black dragons under Nefarion hold the spire's upper levels, and the two groups battle constantly for supremacy. The surrounding countryside is home to Blackrock orcs and Fire-Gut ogres, all brutal castoffs from the Second War. The Molten Span, a massive stone edifice in the north, bridges a river of fire and leads to Khaz Modan.\n\nWhile many use the Burning Steppes as a thoroughfare, it is populated by one of the few successful orc settlements in Azeroth. These orcs do not honor Thrall's truce with the Alliance, instead following the barbaric practices the orcs used from before the Third War. Deeper into the region, ogres, dragons, and the Dark Iron clan of dwarves can be found. With the volcanic activity and lava flow, the weather is perpetually hot and dry.\n\nThe Burning Steppes are located north of the Redridge Mountains and south of the Searing Gorge. It is dominated by Blackrock Mountain in the northwestern area. It is a central location housing the black dragonflight and various creatures. It also has quite a few high-level instances. It is recommended that characters be at least level 55, as the creatures are some of the most powerful in the game.\n\nThe Blackrock orcs maintain a lasting settlement around the volcano known as Blackrock Stronghold, staying hidden from the road but always keeping watch for Alliance attacks. These orcs are more typical of the type of the First and Second wars rather than the current Horde in Kalimdor. Bloodthirsty and savage, they mine the mountains around Blackrock Spire for metals with which to make weapons and armor. The Firegut ogres from the south study arcane magic, but their massive bodies still allow them to excel in combat. Give an ogre sorcerer a club and she's still likely to bash out the brains of the strongest dwarven fighter. This violent race is dedicated solely to claiming the Burning Steppes as ogre territory. The Alliance -- not to mention the orcs, the Dark Iron dwarves and the dragon folk -- will not let this happen, as they refuse to lose control of the only passage to the north. The black dragons are elusive, and one who wishes to avoid getting torn apart doesn't approach without considerable firepower. They will attack solitary travelers for sport and consider anyone approaching their usurped fortress free game.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Elwynn Forest",
		short = "Elwynn Forest is the starting zone for playable humans.",
		full = "Elwynn Forest is the starting zone for playable humans.\n\nNorthshire was the pride of Stormwind's vineyards until recently when Defias bandits drove off the farmers and occupied the farm and fields. In addition, the Echo Ridge Mine north of the abbey has been infested by kobolds.\n\nKobolds infested the Jasperlode Mine and Fargodeep Mine. Gnolls have erected camps in the Forest's Edge region and the northern rim of Stone Cairn Lake. It is rumored that both the kobolds and gnolls are somehow associated with the Defias Brotherhood. Murlocs have taken up residence in and around Stone Cairn Lake and Crystal Lake. Defias presence in the region has been growing and their people have holdings at Mirror Lake Orchard, Northshire Vineyards, the Brackwell Pumpkin Patch, Jerod's Landing and Stone Cairn Lake.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Deadwind Pass",
		short = "Deadwind Pass is a contested zone located in central Azeroth, joining the southeastern reaches of the Kingdom of Stormwind (via Duskwood) from the east to the Swamp of Sorrows (and, eventually, the Dark Portal in the Blasted Lands) from the west.",
		full = "Deadwind Pass is a contested zone located in central Azeroth, joining the southeastern reaches of the Kingdom of Stormwind (via Duskwood) from the east to the Swamp of Sorrows (and, eventually, the Dark Portal in the Blasted Lands) from the west. It was, a score of years ago, considered a part of the Redridge Mountains.\n\nThe Ivory Tower of Karazhan, once the dark wizard Medivh's seat of power, stands in the center of this jagged region and leaks evil magic into the land. The trees are petrified and leafless, and a terrible wind keens through the canyon. Ogres, demons, undead and a few human gypsies roam the interior. Deadwind Pass connects Duskwood and the Swamp of Sorrows, and travelers are advised to move quickly -- whispers tell that a new force has claimed the Ivory Tower, and that the ogres and demons are under its sway.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Duskwood",
		short = "Duskwood is located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale.",
		full = "Duskwood is located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale. Technically part of the Alliance and under Stormwind's protection, its distance from the mighty fortress and its close proximity to more malevolent forces in the south and east make it a realm of horror. Due to events central to the Scythe of Elune, Duskwood is a cursed, dying land. Beneath the eternal blanket of darkness which gave Duskwood its current name, the Scythe's effects have transformed what was once a beautiful part of Elwynn Forest into a land covered in gnarled trees and inhabited by the hideous undead and extradimensional Worgen, brought along with the black fog hanging over the woods. Ogres moving in from Deadwind Pass have brought up even more problems.\n\nLong betrayed and abandoned by Stormwind, Duskwood is inhabited by a defiant people who still cling to their holdings in the face of overwhelming adversity. On all sides lurk dangerous creatures, from skeletal warriors and ghouls to ferocious worgen and some of the most powerful members of the Defias Brotherhood. The militia of Duskwood, known as the Night Watch, patrol the main thoroughfare and protect Darkshire, wary of anything moving through the shadows.\n\nThe most prominent geographical feature of Duskwood is an ancient and long-dead volcano crater. The crater teems with life, and features one of the Great Trees with a portal leading into the Emerald Dream. The sleeping druids' influence can be seen on the surrounding land, which is cloaked in a twilight quite different from the rest of Duskwood. The woods also feature several abandoned farmsteads, as well as the prominent Raven Hill Cemetery, which holds the graves of the numerous people who have been killed by wild beasts and undead since the darkness fell.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Loch Modan is a large area east of Dun Morogh, situated in eastern Khaz Modan. The gray and rugged Khaz Modan mountains rise up on all sides around the loch, and the hills are lightly wooded with pine and birch.",
		full = "Loch Modan is a large area east of Dun Morogh, situated in eastern Khaz Modan. The gray and rugged Khaz Modan mountains rise up on all sides around the loch, and the hills are lightly wooded with pine and birch. The loch was held in place by the now broken Stonewrought Dam, an architectural wonder of no equal on Azeroth.\n\nLoch Modan is heavily populated by hostile troggs, unearthed from caves below ground by the dwarven digs. They have since settled in the surrounding mountainous area and built crude camps and caves from which to strike at passing travelers. Other dangers include dangerous wildlife, aggressive kobolds, and the powerful ogres of the Mo'grosh Stronghold.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Redridge Mountains",
		short = "The Redridge Mountains, or the Red Ridge Mountains, are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes.",
		full = "The Redridge Mountains, or the Red Ridge Mountains, are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes. Although it may be considered contested, Horde characters have no settlements or NPCs and it is thus a place they use mostly for passing through to reach Flame Crest or Stonard.\n\nAn idyllic region of rushing rivers, towering elms and rising elevations, the Redridge Mountains are under Stormwind's protection (though since the second war it is technically independent), and remain one of the last peaceful regions in Azeroth. The people are content and calm, and supply Stormwind with timber, fish, and crops. A force of Blackrock orcs from the Burning Steppes has secured Stonewatch Keep, but so far the orcs keep to themselves. In comparison with Westfall, Redridge is still relatively stable.\n\nOn the northern bank of Lake Everstill is the Alliance town of Lakeshire, the central hub for this faction's adventurers, offering many services and quests, as well as flight paths. As the town is under constant siege by gnolls and Blackrock orcs, adventurers should use extreme caution around this town.\n\nThe enemy-held Stonewatch Keep and Tower of Ilgalar are connected with quests, but are also very dangerous and require a party to handle properly.\n\nThe crossroads known as the Three Corners, located in the southwest corner of the zone, connects the town of Lakeshire with Elwynn, Duskwood and, via the Lakeridge Highway, Stonewatch Keep. The highway itself is quite a dangerous place occupied by dragon whelps, gnolls, murlocs, and wild animals. There are also a few camps located in Redridge -- an orc camp in Render's Valley, Shadow Hide gnoll camps near the Tower of Ilgalar, and murloc camps near the lake. While the lake's surface appears peaceful enough, murlocs reside beneath the waves, and rumours of sightings of a sea monster persist.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Stranglethorn Vale",
		short = "Stranglethorn Vale is a vast jungle south of Duskwood.",
		full = "Stranglethorn Vale is a vast jungle south of Duskwood.\n\nJungle trolls patrol this steaming rainforest. Ancient Gurubashi trolls once ruled the region, and the ruins of their great cities crumble in the jungle's heat and growth. Naga hunt along the coast and vicious animals and plants, including the eponymous strangle-thorns, make travel dangerous. The Arena, a center for gladiatorial games set in a ruined Gurubashi fighting stadium, draws shady characters of all races. The Blackwater Raiders, a vile group of pirates, make their home in Booty Bay, on the Stranglethorn's southern coast.\n\nThe Vale was the primary center of the trolls of the Gurubashi Empire, and their cities were dotted all over the region. After the Empire's fall the cities of the troll empire fell into ruin, although they are still populated by trolls. In recent years, the Humans of Stormwind attempted to forge trade routes through this savage jungle. Though they managed to establish the small port town of Blackwater Cove, they were quickly overwhelmed by a crazed pack of Trolls and driven back to their homeland. In the wake of the Humans' departure, the crafty Goblin Trade Princes arrived on the jungle's shores and quickly set up their mining and deforesting operations. The Goblins have maintained a tenuous hold over these remote facilities, but they remain threatened by the Jungle Trolls' growing obsession with purging their ancient lands of any and all foreign invaders.\n\nStranglethorn is as deadly as it is beautiful. It is inhabited by a large variety of beasts and hostile creatures that low level characters should not face alone. The primary sapient inhabitants are the Bloodscalp and Skullsplitter trolls, in the northwest and east respectively. The troll city of Zul'Gurub sits in a valley in the northeast, which was once the capital of Troll civilization in Stranglethorn. In the north is a small village controlled by the renegade Colonel Kurzen. Other inhabitants include an encampment of ogres. Off the southeast coast is Jaguero Isle, inhabited by the enormous gorilla King Mukla. There is a renegade group of sailors, known as the Bloodsail Buccaneers, who have built camps on the southwestern and southern shores of Stranglethorn Vale. A small population of naga can be found in the southwest, and murlocs inhabit some underwater ruins in the northwest. The Venture Company also has two mining operations in Stranglethorn. In the northwest, the Zandalar Tribe has its base in Yojamba Isle. The water gate from the Deadmines can also been seen north of Yojamba Isle, though it cannot be entered.\n\nThe weekly Stranglethorn Fishing Extravaganza event happens every Sunday from 2-4pm.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Swamp of Sorrows",
		short = "The Swamp of Sorrows (also once known as the Swamps of Sorrow) is a contested territory in the southern part of the Eastern Kingdoms.",
		full = "The Swamp of Sorrows (also once known as the Swamps of Sorrow) is a contested territory in the southern part of the Eastern Kingdoms. Among its murk-ridden marshes the green dragonspawn patrol at the behest of their dreaming mistress, Ysera. The great Dragon Aspect has warned of a lurking terror within the Temple of Atal'Hakkar, and her loyal servants are determined to protect the land from the emerging doom.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "Westfall borders the Kingdom of Stormwind and is mostly populated by humans not under the Alliance's complete control. The region was stolen right under the Alliance's nose by its own bitter people.",
		full = "Westfall borders the Kingdom of Stormwind and is mostly populated by humans not under the Alliance's complete control. The region was stolen right under the Alliance's nose by its own bitter people. This rich land has lain fallow since the Second War, but it is now held by the Defias Brotherhood. Stormwind claims the land as its own, but it has found little time to be concerned with it, with insufficient funds and might to retake the region. A handful of farmers still try to keep their land, and some even attempt a tithe to Stormwind every year, but most only grow enough to feed themselves. The Defias Brotherhood controls much of the region, focused in the southern area of Moonbrook.\n\nOnce a rich agricultural center, much of Westfall now lies fallow and forgotten. The Defias Brotherhood, renegade humans who wield secrecy and technology against Stormwind, control much of the area. Bandits and gnolls raid those farms that remain, and Stormwind's resources are stretched too thin to protect the beleaguered populace. Westfall has the mild temperatures of Elwynn, but winds batter it both from the sea and from Duskwood. The bare farmlands add little to break the wind, which can cut through clothing on a blustery day.\n\nWestfall is a region of rolling pastures and farms that were once beautiful and green, but now have become barren with drought and maltreatment at the hands of bandits. The grass is yellowed and the fields are infested with ravenous carrion birds and mechanical harvest watchers gone rogue. The outlawed Defias Brotherhood has gained a strong foothold in Westfall and controls several camps and farmsteads in the area. It is rumored that these bandits possess a large mine with an entrance somewhere in the small town of Moonbrook, and that they have connections with the kobolds that occupy the Jangolode Mine in Westfall and the various mines in Elwynn Forest.\n\nThe People's Militia has erected a last bastion of military power in the region at Sentinel Hill, from where they issue commands to anyone willing to aid the cause. Although most of the area's farms have fallen to disrepair and passed into control of the Defias, there are still a number of farmers who bravely (and desperately) cling to their holdings in spite of overwhelming odds.\n\nAlso, note that on PvP servers and even some PvE servers high-level Horde players enjoy killing human NPCs at Sentinel Hill.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Wetlands",
		short = "The Wetlands is a large, wet zone below Stonewrought Dam and north of Loch Modan, covered with small rivers, lakes, and ponds. Bordered on three sides by mountains, the Wetlands are open to the ocean to the west.",
		full = "The Wetlands is a large, wet zone below Stonewrought Dam and north of Loch Modan, covered with small rivers, lakes, and ponds. Bordered on three sides by mountains, the Wetlands are open to the ocean to the west. Adventurers seeking a route to the Wetlands must either come through sieged Dun Algaz from Loch Modan or cross the damaged Thandol Span from Arathi Highlands. The northern slopes of Wetlands are generally classed within mountains of Khaz Modan.\n\nThe Wetlands is a vast, cold swamp. Mists cloak the ground, and the overcast sky makes the land a uniform gray. Many Ironforge strongholds once stood in this region, but war has reduced them to rubble. Wild creatures, murlocs and renegade orcs now control the land. Menethil Harbor, a city on the west coast, is the Alliance's only presence in this dreary region.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Off Kalimdor's northern coast lies the island, and great tree of the same name, Teldrassil, the new home of the reclusive night elves and a stunning testament to the power of their magic and their connection with nature.",
		full = "Off Kalimdor's northern coast lies the island, and great tree of the same name, Teldrassil, the new home of the reclusive night elves and a stunning testament to the power of their magic and their connection with nature.\n\nIn recent times, the night elves have moved their capital to an island off northwest Kalimdor. It was here that the Circle of Ancients and the wise druids pooled their power to create another World Tree, but on a smaller scale. They called this tree Teldrassil (\"crown of the earth\") and built their city of Darnassus atop it. The island takes the name of the \"tree\" as well, and a twilit forest now covers it.\n\nTeldrassil is truly massive, a huge trunk rising out of the sea and holding the entire night elf homeland, and the capital of Darnassus, in its boughs. The enterprise was not blessed by the Aspects, however, and the tree's growth has been flawed. Regardless, the behemoth of a tree dwarfs Nordrassil, even large enough that a decently large amount of land has emerged atop its gargantuan limbs. Trees, flora, and fauna are now verdantly spreading across the magical tree.\n\nTeldrassil sees very little PvP action due to the fact that Horde players have to cross through Darnassus. The only way for Horde players to get to Teldrassil itself is via ship from Auberdine on mainland Kalimdor. Most other starting areas are directly accessible by the opposing faction without such hazards.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Darkshore",
		short = "Darkshore is a long strip of coast on the northwestern part of Kalimdor. It is known for its characteristically shadowed woods and rocky beaches, littered with ancient ruins and mountainside caves.",
		full = "Darkshore is a long strip of coast on the northwestern part of Kalimdor. It is known for its characteristically shadowed woods and rocky beaches, littered with ancient ruins and mountainside caves. The night elves of Teldrassil claim the shore as part of their new kingdom, and sentinels patrol the road from the port of Auberdine towards Ashenvale to the south.\n\nThis rocky area stretches along Kalimdor's north coast. Rains, winds and rocky beaches make the place inhospitable. Old night elf ruins stand crumbling on the cliffs, and murlocs and naga lurk within. The night elf village of Auberdine serves as a friendly trading post.\n\nThe region is not without dangers, however. Aggressive wildlife roams the grassy hills and stalks among the dark trees. The ruined cities of the night elves are infested with naga, satyrs, grells and haunting ghosts, and cultists of the Dark Strand and Twilight's Hammer ambush unwary travelers from their hideouts beyond the road. Even the seas are unsafe, as bloodthirsty frenzies, gigantic threshadons, and hostile murlocs lurk beneath the waves.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Ashenvale, also known as Ashenvale Forest, is a wilderness region south of Darkshore and Felwood, west of Azshara, and north of the Stonetalon Mountains and the Barrens.",
		full = "Ashenvale, also known as Ashenvale Forest, is a wilderness region south of Darkshore and Felwood, west of Azshara, and north of the Stonetalon Mountains and the Barrens. Ashenvale is also the term used for the larger forested region which includes most of western Hyjal including Azshara. It is the ancestral homeland of the night elves, who remain in control of several holdings through the zone, including Astranaar, Maestra's Post, Silverwind Refuge, Silverwing Grove, and the Shrine of Aessina. The Horde has more recently established a settlement in the eastern part of the woods -- Splintertree Post -- as well as a smaller camp on the western beach -- Zoram'gar Outpost - along with several Warsong camps situated from Kargathia Keep all through the southeast to the Mor'shan Rampart in the far south. The zone is heavily populated with furbolgs, satyr, and wild creatures such as spiders, wolves, and bears. The region is quite large, and running from the Zoram Strand to the Warsong Lumber Camp is quite an undertaking.\n\nSince the zone is contested there is often a lot of skirmishing going on throughout the woods, and attacks on the faction-based settlements are not uncommon. The zone is also a major travel hub for both Horde and Alliance, even at higher levels.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Thousand Needles",
		short = "Thousand Needles (aka The Thousand Needles) is a huge dry canyon in Southern Kalimdor, filled with towering mesas.",
		full = "Thousand Needles (aka The Thousand Needles) is a huge dry canyon in Southern Kalimdor, filled with towering mesas. In the east, the canyon opens up to the Shimmering Flats, a vast salt pan that is used by Goblin and Gnomish engineers for their races. Despite being relatively barren, the area has its own harsh beauty, and the sunrise seen from either Freewind Post or one of the mesas around Darkcloud Pinnacle can be spectacular. The Shimmering Flats and Mirage Raceway are also worth visiting for their surreal, lonely atmosphere.\n\nAlthough as a contested territory this area doesn't see anywhere near as much action as some, Darkcloud Pinnacle is a favorite stealth ganking spot for Alliance rogues due to the many Horde quests there as well as the relative difficulty of the mobs/remoteness of that location. The Alliance also tend to attack the Great Lift and Freewind Post fairly regularly. In addition, players questing on the Shimmering Flats near the Tanaris border are advised to look over their shoulder from time to time, as the unwary can occasionally find themselves being stabbed in the back by a passing member of the opposing faction.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Stonetalon Mountains",
		short = "The Stonetalon Mountains, aka Stonetalons, are a range of peaks that lie west of the Barrens, south of Ashenvale, and north of Desolace.",
		full = "The Stonetalon Mountains, aka Stonetalons, are a range of peaks that lie west of the Barrens, south of Ashenvale, and north of Desolace. The mountains are traditionally the homeland of the harpies, but their numbers have dwindled as the bird-women spread east and south. Stonetalon Peak, the largest mountain in the range, has long been a sacred place for both the night elves and tauren. The night elves maintain a barrow and a glade at the top, where they commune regularly with the spirits of nature. The mountains further south are less forested, although some sparse evergreens grow in certain spots, particularly the Greatwood Vale. The Venture Company have put a heavy toll on the land, cutting down almost all the trees in Windshear Crag and filling the air with soot, spoiling the area's water with oil and waste much to the fury of the orcs and tauren. The tauren have a holding in the centrally located Sun Rock Retreat and the Darkspear trolls have a settlement further south at Malaka'jin. The mountains are also home to kobolds, spiders, and wyverns, while Charred Vale holds several especially dangerous kinds of beasts and elementals.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "In Desolace, the skulls of ancient kodo beasts stare soullessly from their graves, halfway buried in dust.",
		full = "In Desolace, the skulls of ancient kodo beasts stare soullessly from their graves, halfway buried in dust. The husks of long-dead trees jutting in gruesome angles from the gray ash are the only twisted remains of a verdant past.\n\nThis dour setting is violently jarred by the thunder of thousands of hooves and the clamor of armor and weaponry as the four tribes of vicious centaur wage war on all who enter their domains, including one another. Desolace is the home of the centaur. It was among the twisting cliffs of the western canyons that their race was born from the foul womb of Maraudon.\n\nProud, but sorrowful ruins of stone attest to the one-time glory of the Highborne night elves. Blasted in the depths of time by the shock waves of the Great Sundering, the ruins are inhabited now by all manner of foul creatures.\n\nDesolace today is a battleground for many of the opposing factions represented here. Apart from the tension between the Horde and the Alliance, at Shadowprey Village and Nijel's Point respectively, the Kolkar, the Gelkis, the Magram, and the Maraudine centaurs fight as much against each other as they do against the orcs and the humans. In the meantime, the demons and satyrs summoned by the Burning Blade increase the risk of a region-wide demonic infestation and present a major challenge for both the Horde and the Alliance. The naga presence to the northwest is also rapidly becoming a source of concern.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Unlike its barren neighbors to the north, south and east, Feralas is a lush jungle.",
		full = "Unlike its barren neighbors to the north, south and east, Feralas is a lush jungle. Both the Horde and the Alliance lay claim to the area and both factions have to contend with powerful local forces, which include, most notoriously, the bloodthirsty Gordunni ogres which populate the region and control a number of ancient Elven ruins scattered in the area, including the vast dungeon of Dire Maul. Gordunni ogres have desecrated and defiled much of Feralas and have damaged the land with their taint. The Horde, in particular, is concerned with the unchecked expansion of the Gordunni clan and has put out a call for adventurers to aid the war effort against the Ogres. Feralas is also home to a number of scattered Grimtotem tauren tribes, members of which are hunted by Horde agents on the orders from Belgrom Rockmaul in Orgrimmar. In addition the far western islands are crawling with Naga and recently several Silithid hives have been spotted in the region.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Dustwallow Marsh",
		short = "Dustwallow Marsh is a vast and ancient swamp in Central Kalimdor that is home to many old and wonderful beasts.",
		full = "Dustwallow Marsh is a vast and ancient swamp in Central Kalimdor that is home to many old and wonderful beasts. Navigation is often extremely difficult and many adventurers have lost their way in this great jungle, where trees obscure the sunlight and raptors, spiders, and crocolisks lie in wait, hunting those brave enough to venture close to their lairs.\n\nA hot, fetid swampland, Dustwallow Marsh is fed by underground springs that keep it eternally wet and muddy. Mosquitoes buzz in the air. Trees dip fronds into the waters. The climate is home to a variety of predators, including crocolisks and murlocs. Black dragons dwell in the southern end of the swamp in such profusion that the area garners the name \"Wyrmbog\". Dustwallow Marsh abuts the ocean on its east side, and the mixing of the waters makes a wide swath brackish. Off the coast is a rocky island, on which is perched the Alliance stronghold-city of Theramore.\n\nNear the low hills that form the western edge of the Marsh separating it from the Barrens, the Stonemaul ogre tribe have opened their Brackenwall Village to the races of the Horde. Brackenwall serves as an essential foothold for the Horde in the marshlands.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Tanaris is a desert located in southeastern Kalimdor, east of Un'Goro Crater and south of Thousand Needles. It is an arid land, covered in sand dunes and frequently exposed to dangerous sandstorms.",
		full = "Tanaris is a desert located in southeastern Kalimdor, east of Un'Goro Crater and south of Thousand Needles. It is an arid land, covered in sand dunes and frequently exposed to dangerous sandstorms. The Steamwheedle Cartel has its main base of operations here - Steamwheedle Port and Gadgetzan have been founded by the goblins of Undermine since this desert is as close to home as they can get on the continents. The dock in Steamwheedle is presumably used for transport to the outer islands, but so far, the goblins have proved unwilling to share the ships with the other races.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Azshara is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar. It is a beautiful coastal area cloaked in eternal autumn.",
		full = "Azshara is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar. It is a beautiful coastal area cloaked in eternal autumn. The trees and other flora are tinged in brilliant oranges and reds, and nearer the coast, great cliffs and sandy beaches line the ocean. The region's inhabitants can make life hard for the nature lover, however. Enraged ghosts, vicious satyr, stalking naga and ferocious wildlife can quickly put an end to those who venture too far from the road.\n\nA shattered stretch of coastline on Kalimdor's northeast, Azshara was once the greatest night elf metropolis. The city fell millennia ago in the War of the Ancients, but a few ragged buildings perch on the cliffs overlooking similar ruins among the coral. Much of the city of Azshara fell into the ocean. The Horde has established a small outpost, Grim Ulang, in the area, but naga are a constant danger.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Felwood",
		short = "Felwood, aka Felwood Forest, is a contested zone located north of Ashenvale, east of Darkshore, and west of Hyjal and Winterspring.",
		full = "Felwood, aka Felwood Forest, is a contested zone located north of Ashenvale, east of Darkshore, and west of Hyjal and Winterspring. It is a corrupted forest filled with tainted creatures of the woods, demonic satyr and infernals, rotting treants and ancients, as well as the tauren and night elves who try to battle back the sickening of the land. It is also home to one of the two tribes of pure furbolgs left in the world -- the Timbermaw.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro Crater",
		short = "Lush Un'Goro Crater (\"God Lands\" in the Qiraji language) lies at the southern part of Southern Kalimdor, between Tanaris and Silithus.",
		full = "Lush Un'Goro Crater (\"God Lands\" in the Qiraji language) lies at the southern part of Southern Kalimdor, between Tanaris and Silithus. Although the area is almost completely isolated from the rest of the world and sandwiched between three deserts, the region is filled with exotic plant life and even more exotic creatures. Ranging from peaceful earth elementals to raging devilsaurs, the locals are not to be trifled with.\n\nThe pylons on the ridges of the crater defy explanation, despite close examination. They could mark where the titans might reappear during their second visit to Azeroth, a visitation supported by holograms both in Uldaman and in front of Uldum.\n\nUn'Goro Crater was revealed to have some connection with the titans by Geologist Larksbane during the Ahn'Qiraj solo quests.\n\nUn'Goro is known for many of its popular culture references, in particular, the myriad Nintendo characters and places. It also has a real world basis called Ngorongoro Crater.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "The Moonglade (also spelled Moonglades and Moon Glade) is a vale in Northern Kalimdor that serves as a haven for druids, and is also the home of the Cenarion Circle.",
		full = "The Moonglade (also spelled Moonglades and Moon Glade) is a vale in Northern Kalimdor that serves as a haven for druids, and is also the home of the Cenarion Circle. Moonglade's reflection within the Emerald Dream is the most sacred place in the entire realm. Here, tauren and night elves coexist peacefully, united by their reverence for the spirit of nature. Conflict between the races in Moonglade is not tolerated by the Moonglade Wardens stationed throughout the main town of Nighthaven, who will respond to any violence initiated against individuals with a favorable reputation with the Circle.\n\nThe demigod Omen sleeps at the depths of the central lake, awakening every year around the time of the Lunar Festival, after which he is routinely put to rest. The Lunar Festival itself is based in Nighthaven and the Moonkin Festival also occurs in the area. In a corrupted version version of the Moonglade located within the Emerald Nightmare, an entrance to the Rift of Aln can be found.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Silithus forms the south-western corner of Kalimdor. It can only be reached by traveling to the north-western corner of the Un'Goro Crater, where a wide path extends out of the crater and into Silithus.",
		full = "Silithus forms the south-western corner of Kalimdor. It can only be reached by traveling to the north-western corner of the Un'Goro Crater, where a wide path extends out of the crater and into Silithus.\n\nSilithus is one of the insect-infested sections of southern Kalimdor. This area houses a section of the once great Aqiri empire, known as Ahn'Qiraj. It is currently uninhabited, but the central temple is sealed off by the night elves, who attempted to prevent an infestation from breaking out. Judging by the ruins in the area, as well as the massive Silithid colonies, they were unsuccessful in their attempt. The Cenarion Circle maintains a constant presence in Silithus, at Cenarion Hold. From here, they monitor the Silithids, whom some believe to be a force so powerful and threatening that the Alliance and Horde must ally to combat. In addition to the Cenarion Druids, a second, more ominous presence has recently made itself known in Silithus. The bronze dragonflight, Nozdormu's brood, has returned to the desert for the first time in ten thousand years.\n\nSilithus has been fleshed out as a major quest hub with episodic storylines that extend into its depths and past its borders. The redesign of this zone includes a high-end outdoor quest area for the solo players, 5-man groups and includes outdoor raid bosses. The repeatable quests can lead to epic items as a casual alternative to raid dungeons.\n\nA new crystalline substance, called \" [Silithyst]\", has been discovered, and both the Horde and the Alliance have taken an interest in it. Players collect the dust where they can, but must be careful they are not ambushed by opposing faction members before they can make their drop off. See The Silithyst Must Flow for details.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Winterspring (aka Winterspring Valley or Winterspring Grove) is a valley located in northeastern Kalimdor, east of Felwood and Hyjal, and north of Azshara.",
		full = "Winterspring (aka Winterspring Valley or Winterspring Grove) is a valley located in northeastern Kalimdor, east of Felwood and Hyjal, and north of Azshara. It is a cold land perpetually covered in snow and holds the goblin city of Everlook, old night elf holdings, and the traditional homeland of the blue dragonflight. Many wild creatures roam the beautiful landscape. However, the southern parts of the region have been completely taken over by demons.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind City",
		short = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth.",
		full = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth. Located north of Elwynn Forest on Azeroth region's northwest coast, it has become one of the last great human cities after the Third War, and embodies the heart of the Alliance. Stormwind's willingness to work with others to find diplomatic solutions stands out as one of its true strengths. Its citizens hold fast to the principles of honor and justice as they defend their settlements and the Alliance against any aggressors.\n\nNo city better demonstrates human determination than Stormwind. Destroyed by the Orcish Horde during the First War, the capital was painstakingly reconstructed by the Stonemasons' Guild after the Second War. From the magnificent Cathedral of Light, which serves as a major spiritual hub, to the awe-inspiring Valley of Heroes, which commemorates the sacrifices of Stormwind's loyal champions, the city truly represents the courageous heart of humanity, and serves as a bastion of the Holy Light.\n\nThe Stormwind City Guard are the law enforcement and protectors of Stormwind City, keeping the peace within the city's walls.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole.",
		full = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole. Named in honor of the legendary Orgrim Doomhammer, and nestled into a system of valleys on the northern edge of Durotar, Orgrimmar stands as one of the mightiest warrior cities in the world. It is the seat of the Horde Council that governs the entire faction. It is the primary hub for player characters of the Horde and, as with all capital cities, has banks, class and profession trainers, and auction houses.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance.",
		full = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance. Carved into the depths of Ironforge Mountain in northern Dun Morogh, it is the ancestral home of the dwarves and one of the oldest cities on Azeroth. The Council of Three Hammers rules over the city to ensure the fair and equal treatment of all dwarves within its walls from the High Seat. The city is also the capital of the Kingdom of Khaz Modan, which is ruled by the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital and a testament to the dwarves' strength and resilience. The city consists of a series of concentric rings, with the smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. Ironforge is perhaps the most intricate of the Alliance cities, boasting many small passageways, shops built into the rock walls, and cavernous rooms. The feel of the city is a bustling, rowdy, and somewhat industrial one, where there are always a thousand things happening at any time of the day or night. However, it is predominantly safe-feeling and cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Also, unlike Stormwind and Darnassus, the city is actually a massive cavern carved into the earth by the dwarves; the ceiling and floor are both hard stone.\n\nMainly because of the Deeprun Tram, linking Ironforge and Stormwind City, and the district of Tinker Town, Ironforge is one of the most racially diverse cities in the Alliance world. With the Council of Three Hammers uniting all three dwarven clans, Ironforge has recently welcomed Dark Iron dwarves and Wildhammer dwarves into Ironforge as well.\n\nThe collective frivolity, the bustling and gruff manner of the dwarves, and the proximity to many quest and raid areas have historically made Ironforge, along with Stormwind City, a popular place to idle.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor.",
		full = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor. The entire city is built on bluffs several hundred feet above the surrounding landscape and is accessible by elevators on the southwestern and northeastern sides. Established by the wise chieftain Cairne Bloodhoof and his stalwart tribe, Thunder Bluff overlooks the verdant land of Mulgore from atop a series of windswept mesas. Prior to the construction of the capital, the tauren had lived as nomads for countless generations, often under attack by marauding bands of centaur. With Thunder Bluff's founding, however, the proud and good-spirited race was finally granted a permanent home.\n\nThe city of many tribes is a hub for tauren, welcoming tradesfolk and artisans of every kind.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil.",
		full = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil. The High Priestess, Tyrande Whisperwind, resided in the Temple of the Moon, surrounded by other sisters of Elune and her mate, the Archdruid Malfurion Stormrage.\n\nDarnassus was the greatest city of the night elves, housing the leaders of both the druids and the faithful of Elune. It was carefully guarded by Sentinels, ancient protectors, and ancients of war. It was destroyed during the Burning of Teldrassil.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades.",
		full = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades. Originally intended by Arthas Menethil to be the Scourge's seat of power in Lordaeron, the budding \"Undercity\" was abandoned when the death knight was recalled by the Lich King in the distant Northrend. During the Plaguelands civil war, Sylvanas Windrunner and the Forsaken rebels claimed the Undercity for their own, then spent years completing the twisted maze of catacombs the Scourge had begun constructing. It was much more defensible than the city above it.\n\nPlagued by the Banshee Queen during the Battle for Lordaeron, its surface has since been cleansed by the efforts of the Desolate Council.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}
